std::tuple<long long, long long, long long> stats(const std::vector<long long> &v) {
    long long lo = v[0], hi = v[0], sum = 0;
    for (long long x : v) {
        lo = x < lo ? x : lo;
        hi = x > hi ? x : hi;
        sum += x;
    }
    return {lo, hi, sum};
}

int main() {
    std::vector<long long> v;
    long long x;
    while (std::cin >> x) {
        v.push_back(x);
    }
    if (v.empty()) {
        std::cout << "пусто\n";
        return 0;
    }
    auto [lo, total, hi] = stats(v);
    std::cout << "минимум " << lo << ", максимум " << hi << ", сумма " << total << '\n';
    return 0;
}

